import { edit_delete_payslips } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    payslipDeletion: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_event() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_delete_payslips, {
          input: {
            payslip_id: this.rowInfo.payslip_id,
            action_type: "DELETE_PAYSLIP"
          }
        }));
        var response = JSON.parse(result.data.edit_delete_payslips);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
